%[text] # NHE6 regulated endosomal pH
pwd %[output:77687c73]
cd("/Users/ritesh/Desktop/Prof_hari/simulation/ritesh_simulation/")
pwd %[output:18338bae]
%%
%[text] ## Loading the fold change in number of NHE6
% clear all; close all;
NHE6_fold_changes = table2array(readtable('NHE6_data.xlsx'));
%%
%[text] ## Initial conditions for running the sims
% Luminal Concentrations
initpH = 7.4;                %{pH [pH units]}
initk  = 0.005;              %{K+ [M]}
initcl = 0.11;               %{Cl- [M]}
initna = 0.145;              %{Na+ [M]}
initH  = 0.00;               %{total H+ [M]}
initV = (4/3*3.1416*0.34^3*1e-12)/1000;
mole = 6.02e23;

initncl = initcl*initV*mole;
initnk = initk*initV*mole;
initnna = initna*initV*mole;
initnH = initH*initV*mole;

% declaring the simulation time and initial conditions
sim_time = 0:10:100000;
initials = [initpH,initncl,initnk,initnna,initnH,initV];

% Initializing the simData variable to be filled
pH_simData = zeros(length(sim_time),length(NHE6_fold_changes));
%%
%[text] ## Running the ODE simulations
% loop for running the ODE for every value of the fold change
for i = 1:length(NHE6_fold_changes)
[t, y] = ode15s(@(t,y) endosomal_ph(t,y,NHE6_fold_changes(i)),sim_time,initials);
pH_simData(:,i) = y(:,1);
end
%%
%[text] ## Determining the steady state time point
% We calculate difference between consequtive steps and find the first
% index below tolerence
time_step_size = 10; % (in sec) - refer to 'sim_time'
time_window = 100;   % (in sec)
% tolerence of pH change to determine steady state
ss_tolerence = 0.01;
% index to get time when steady state is reached
pH_simData_ss_idx = zeros(1,length(NHE6_fold_changes));
% pH steady state values at the steady state indices
pH_simData_ss_values = zeros(1,length(NHE6_fold_changes));
% variable for pHvalues difference 100 sec apart and respective flag
pH_simData_diff = zeros(size(pH_simData,1)-(time_window/ ...
    time_step_size)+1,length(NHE6_fold_changes));
pH_simData_diff_flag = zeros(size(pH_simData,1)-(time_window/ ...
    time_step_size)+1,length(NHE6_fold_changes));
for i = 1:size(pH_simData_diff,1)
pH_simData_diff(i,:) = pH_simData(i,:) - pH_simData(i+( ...
    time_window/time_step_size)-1,:);
[~,pH_simData_diff_flag_temp] = min(pH_simData(i:i+( ...
    time_window/time_step_size)-1,:));
pH_simData_diff_flag(i,:) = pH_simData_diff_flag_temp<2;
end
pH_simData_diff = pH_simData_diff.*pH_simData_diff_flag;
pH_simData_diff(pH_simData_diff==0) = NaN;
% index of when value goes below tolerence for every fold 
% change value is to be stored
for i = 1:length(NHE6_fold_changes)
pH_simData_ss_idx(1,i) = find(abs(pH_simData_diff(:,i))<ss_tolerence,1,'first');
pH_simData_ss_values(1,i) = pH_simData(pH_simData_ss_idx(1,i),i);
end
pH_simData_ss_time_points = pH_simData_ss_idx*time_step_size;

% IMPORTANT NOTE - 
%
% Finding the indices for when steady state is reached is found here
% without any error just cause the tolerence, window size etc somehow were
% in the sweet spot. Since the graph has minima is between and is not
% monotonic, a more rigorous method to determine reaching of steady state
% is required. The above code works but is a jugaad to some extent as well.
%%
%[text] ## Plotting the first 21 simData
figure() %[output:8f82c2d4]
plot(sim_time,pH_simData(:,:),'Color','b'); %[output:8f82c2d4]
xlim([0 8000]); %[output:8f82c2d4]
%%
figure()
plot(sim_time, pH_simData); %[output:513d2fcb]
xlim([0 8000]);
xlabel('Time (s)');
ylabel('Endosomal pH');
box on
%%
% Find the index corresponding to 3000 seconds
idx_3000 = find(sim_time == 3000);

% Extract pH at 3000 seconds for all NHE6 fold changes
pH_at_3000 = pH_simData(idx_3000, :);

% Create table
pH_3000_table = table( ...
    NHE6_fold_changes, ...
    pH_at_3000', ...
    'VariableNames', {'NHE6_fold_change', 'pH_at_3000s'});

% Save
writetable(pH_3000_table, 'pH_at_3000s_all_NHE6.xlsx');
%%
%[text] ## Saving the results
% The results have to be saved in specific tabel format with varibale names
% converting simData to table and renaming fieldnames
pH_simData = array2table(pH_simData);
pH_simData.Properties.VariableNames = strcat(string( ...
    NHE6_fold_changes),'_fold_change');
% converting the, index*timeStep as time taken to attain steady state,
% to table format and renaming fieldnames
pH_simData_ss_time_points = array2table(pH_simData_ss_time_points);
pH_simData_ss_time_points.Properties.VariableNames =  ...
    strcat(string(NHE6_fold_changes),'_fold_change');
% saving these two tables as .xlsx files
writetable(pH_simData,'pH_SimData_allFC.xlsx');
writetable(pH_simData_ss_time_points,'pH_time2SS_allFC.xlsx');
%%
function dydt = endosomal_ph(t,y,fold_changes_nhe6)

dydt = zeros(6,1);

pH = y(1);
Ncl = y(2);
NK = y(3);
Nna = y(4);
NH = y(5);
V = y(6);

% Vesicle Shape Variables (assumes spherical compartment
R = 0.35;                                  %{organelle radius [micron]}
initV = (4/3*3.1416*R^3*1e-12)/1000 ; 	   %{initial volume [lit]}
SA = 4*3.1416*R^2*1e-8 ;                   %{surface area [cm^2]}

% Surface Potentials in mV
psi_out = -20;  			%{outside leaflet [mV]}
psi_in = 0;   				%{inside leaflet [mV]}

% Standard Constants
mole = 6.02e23;             %{Avogadro's Number}
RTF = 25.69;				%{RT/F [mV]}
F = 96485;                  %{Faraday's Constant}
cap_0 = 1e-6;               %{capacitance per unit area [Farad/m^2]}
cap = cap_0*SA/1000;        %{total capacitance [Farad]}
 
% Cytosolic Concentrations
pHbulk = 7.2;               %{pH [pH units]}	
Kbulk  = 0.145;            	%{K+ [M]}
Clbulk = 0.01;              %{Cl- [M]}
Nabulk = 0.01;              %{Na+ [M]}

% Luminal Concentrations
initpH = 7.4;                %{pH [pH units]}
initk  = 0.005;              %{K+ [M]}
initcl = 0.11;               %{Cl- [M]}
initna = 0.145;              %{Na+ [M]}
initH  = 0.00;               %{total H+ [M]}

% set initial total membrane potential [mV]
initpsi_total = 0;
beta = 0.04 ;                %{buffering capacity [mM/pH unit]}

% proton flux interpolation from data
raw_data = dlmread('data.txt');
pH_range = raw_data(1,2:end);
psi_range = raw_data(2:end,1);
data = raw_data(2:end,2:end);
[x,y] = ndgrid(pH_range,psi_range);
proton_flux = griddedInterpolant(x,y,data');

% Kinetic Parameters----------------------------------------
P = 6e-5;                    %{H+ permeability}
Pcl = 1.2e-5;                %{Cl+ permeability}
Pk =  7.1e-7;                %{K+ permeability}
Pna = 9.6e-7;                %{Na+ permeability}
Pw = 0.0;                    %{Water permeability}
N_VATP = 40;%55;               %{Number of V-ATPases}
N_CLC = 60;%100;                 %{Number of ClC antiporters}

CLC_Cl = 2;                  %{ClC Cl- Stoichiometry}
CLC_H = 1;                   %{ClC H+ Stoichiometry}

Oc = 0.291;                  %{Cytoplasmic Osmolarity [M]}
oh =  0.73;                  %{H+ Osmotic coefficient}
ok =  0.73;                  %{K+ Osmotic coefficient}
ona = 0.73;                  %{Na+ Osmotic coefficient}
ocl = 0.73;                  %{Cl- Osmotic coefficient}

% Functions/Conversions---------------------------------

% Luminal Concentrations
Cl = Ncl/V/mole;
K = NK/V/mole;
H = NH/V/mole;
Na = Nna/V/mole;

% Modified Cytoplasmic Surface Concentrations
Cle = Clbulk*exp(psi_out/RTF);
Ke = Kbulk*exp(-psi_out/RTF);
Nae = Nabulk*exp(-psi_out/RTF);
pHe = (pHbulk+psi_out/(RTF*2.3));

% Modified Luminal Surface Concentrations
Cli = Cl*exp(psi_in/RTF);
Ki = K*exp(-psi_in/RTF);
Nai = Na*exp(-psi_in/RTF);
pHi = (pH+psi_in/(RTF*2.3));

% Donnan Particles [M]
B = initk+initna+initH-initcl + (0.001*beta*(pHbulk-initpH)) ...
-cap/F/initV*(psi_in - psi_out) - initpsi_total*cap/F/initV;
% +(0.001*beta*(pHbulk-initpH))

% enforce initial osmotic balance
Q = initV*(Oc - (oh*10^(-initpH) + ok*initk + ona*initna + ocl*initcl));

% Membrane Potentials
psi = F*(V*(H+(K+Na)-Cl)-(B*initV))/cap; %{membrane potential [mV]}
psi_total = psi + psi_out-psi_in;        %{total membrane potential [mV]}
% +(0.001*beta*(pHbulk-initpH))

% Proton Pump
Pump_flux = 1*proton_flux(pHi,psi);       %{V-ATPase surface [H+/sec]}
Hpump = N_VATP*Pump_flux;                 %{total proton pump flow [H+/sec]}
 
% ClC Antiporter
clcf = (CLC_Cl+CLC_H)*psi + RTF*(2.3*(pHe - pHi) + CLC_Cl*log(Cle/Cli));
G1 = -0.3*clcf;
G3 = -1.5E-5*clcf^3;
S = 0.5+0.5*tanh((clcf+250)/75);
CLC_rate = S*G1+(1-S)*G3;
CLC = N_CLC*CLC_rate  ;                 %{total ClC turnover [1/sec]}

% NHE6 activity
nhe6f = RTF*log((Nai*(10^(-pHe)))/((10^(-pHi)*Nae)));
Vnhe = 1500; %  s^-1
Knhe = 3*RTF;
% % % Pnhe =  0.4/(1+((pHi/6.6)^10));
Pnhe =  0.3/(1+((pHi/6.6)^10));
NHE6_rate = (Pnhe^2)*Vnhe*(nhe6f/(Knhe+abs(nhe6f)));
Nnhe6 = fold_changes_nhe6*100;%50; 
% 170 since power in Pnhe is 10. Will change accordingly
NHE6 = Nnhe6*NHE6_rate;



% Treatment of singular terms for passive ion flux
if abs(psi)>0.01
gg = psi/(1-exp(-psi/RTF))/RTF;
else
gg = 1/(1 - (psi/RTF)/2 + (psi/RTF)^2/6 - (psi/RTF)^3/24 +(psi/RTF)^4/120);
end


% Passive flows
Hflow = P*SA*(10^(-pHe)*exp(-psi/RTF)-10^(-pHi))*gg*mole/1000;
Clflow = Pcl*SA*(Cle-Cli*exp(-psi/RTF))*gg*mole/1000;
Kflow = Pk*SA*(Ke*exp(-psi/RTF)-Ki)*gg*mole/1000;
Naflow = Pna*SA*(Nae*exp(-psi/RTF)-Nai)*gg*mole/1000;
Jw = Pw*SA*(oh*10^(-pH) + ok*K + ona*Na + ocl*Cl + Q/V - Oc);


dydt(1) = ((-Hpump - Hflow - (CLC_H)*CLC -NHE6 )/V/mole)/(beta);
dydt(2) = - CLC_Cl*CLC + Clflow;
dydt(3) = + Kflow ;
dydt(4) = + Naflow ;
dydt(5) = Hpump + Hflow + (CLC_H)*CLC -NHE6 ;
dydt(6) = Jw/(1000*55);

end

